 17→// MetadataFields provides metadata fields written to every output line.
 18→type MetadataFields struct {
 19→	Agent      string // e.g. "claude-code"
 20→	CLIVersion string // e.g. "0.42.0"
 21→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 22→}
 23→
 24→// transcriptLine is the uniform output format for every line in transcript.jsonl.
 25→// Field order is guaranteed by encoding/json (struct declaration order).
 26→type transcriptLine struct {
 27→	V            int             `json:"v"`
 28→	Agent        string          `json:"agent"`
 29→	CLIVersion   string          `json:"cli_version"`
 30→	Type         string          `json:"type"`
 31→	TS           json.RawMessage `json:"ts,omitempty"`
 32→	ID           string          `json:"id,omitempty"`
 33→	InputTokens  int             `json:"input_tokens,omitempty"`
 34→	OutputTokens int             `json:"output_tokens,omitempty"`
 35→	Content      json.RawMessage `json:"content"`
 36→}
