660→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
661→func unquote(raw json.RawMessage) string {
662→	var s string
663→	if json.Unmarshal(raw, &s) == nil {
664→		return s
665→	}
666→	return ""
667→}
